<template><main><el-card><h2>AgentCanvas</h2><el-input v-model="email" placeholder="Email"/><el-input v-model="password" type="password" placeholder="Password"/><el-button type="primary" @click="login">Login</el-button><el-button @click="register">Register</el-button></el-card></main></template>
<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{api}from'../api/client';const email=ref(''),password=ref(''),router=useRouter();const submit=async(path:string)=>{const x=await api.post('/api/auth/'+path,{email:email.value,password:password.value});localStorage.token=x.data.access_token;router.push('/')};const login=()=>submit('login'),register=()=>submit('register')
</script>
<style scoped>main{height:100%;display:grid;place-items:center}.el-card{width:320px;display:grid;gap:12px}</style>
